//! Cloudflare Workers bindings generated by ts-gen from `@cloudflare/workers-types`,
//! plus the Rust-side ergonomics (`#[event]`, `Result`, serde, futures, `Router`, `send`)
//! layered on them as `impl` blocks.
//!
//! `src/bindings.rs` is generated; `chomp build:ts-gen-worker:types` regenerates it
//! from `node_modules/@cloudflare/workers-types/index.d.ts` with the `--export`
//! roots listed in `chompfile.toml`.
//!
//! The bindings need js-sys's unstable API (`--cfg js_sys_unstable_apis`). Without it the
//! crate is empty on the host, so workspace-wide host checks skip it, and an error on wasm32.
#![cfg(any(js_sys_unstable_apis, target_arch = "wasm32"))]

#[cfg(not(js_sys_unstable_apis))]
compile_error!("ts-gen-worker needs `--cfg js_sys_unstable_apis` in RUSTFLAGS (see README.md)");

#[allow(clippy::all)]
mod bindings;
mod durable;
mod error;
mod ext;
mod init;
mod router;
pub mod send;
pub mod signal;

pub use bindings::cloudflare::email::EmailMessage;
pub use bindings::cloudflare::sockets::{
    connect, connect_with_address, connect_with_address_and_options, connect_with_options,
};
pub use bindings::*;
pub use durable::DurableObject;
pub use error::{Error, Result};
pub use ext::*;
pub use router::{RouteContext, RouteParams, Router};
pub use ts_gen_worker_macros::{durable_object, event, send};

pub use js_sys;
#[cfg(feature = "url")]
pub use url;
pub use wasm_bindgen;
pub use wasm_bindgen_futures;

/// `ok::Ok(value)` is `Result::<_, Error>::Ok(value)`. A module rather than a crate-root
/// function so that `use ts_gen_worker::*` does not shadow the `Ok` pattern.
pub mod ok {
    #[allow(non_snake_case)]
    pub fn Ok<T>(value: T) -> crate::Result<T> {
        crate::Result::Ok(value)
    }
}

#[doc(hidden)]
pub mod __macro {
    use wasm_bindgen::JsValue;

    pub use ts_gen_worker_macros::consume;

    pub use crate::durable::has_durable_object_attribute;
    use crate::Response;

    /// Logs the handler error and builds the 500 response; `respond_with_errors`
    /// passes the error's `Display` text for the body.
    pub fn error_response(err: JsValue, message: Option<String>) -> Response {
        crate::console.with(|c| c.error(std::slice::from_ref(&err)));
        let body = message.unwrap_or_else(|| "INTERNAL SERVER ERROR".to_owned());
        // Constructing a text response with status 500 cannot throw.
        Response::builder().error(body, 500).unwrap()
    }
}
